import{_ as e,o as a,c as r,a2 as t}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 32 话 Popover API：弹出层的原生答案","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.32-popover.md","filePath":"comics/html/EP.32-popover.md","lastUpdated":1792579602000}'),l={name:"comics/html/EP.32-popover.md"};function d(p,o,i,c,s,h){return a(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="漫画-·-第-32-话-popover-api-弹出层的原生答案" tabindex="-1">漫画 · 第 32 话 Popover API：弹出层的原生答案 <a class="header-anchor" href="#漫画-·-第-32-话-popover-api-弹出层的原生答案" aria-label="Permalink to &quot;漫画 · 第 32 话 Popover API：弹出层的原生答案&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/10-popover">docs/html/10-popover.md</a> ｜ 原画：<a href="./EP.32-popover.svg">EP.32-popover.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>标签君</strong>：HTML5 结构师，本话主角。曾经被弹出层的 z-index 军备竞赛、portal DOM 撕裂、JS 监听全家桶折磨得筋疲力尽。</li><li><strong>像素酱</strong>：CSS 造型师，搬出 <code>popover</code> 属性与 <code>::backdrop</code>，把弹出层交给浏览器原生管——层叠、关闭、焦点，全部内建。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>弹出层曾经是最繁琐的组件：算 z-index、portal 到 body、全局监听外点和 Esc、焦点陷阱与还原、SSR 结构不一致。标签君引入 Popover API——给元素加 <code>popover</code> 属性，<code>popovertarget</code> 声明式绑定按钮，浏览器接管 top layer 层叠、light dismiss、Esc 关闭和焦点管理。像素酱补充 <code>::backdrop</code> 伪元素做遮罩，锚点定位（见 EP.31）补上贴边位置——黄金搭档成型。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>弹出层痛苦全家桶：z-index 9999 不够用，总被 overflow:hidden 裁切，只能 portal 到 body；点击外部关闭、Esc 监听、焦点陷阱与还原全要 JS 自己写；快速连开两层时外点监听互相干扰，是组件库的经典顽固 bug。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>popover</code> 属性 + <code>popovertarget</code> 声明式绑定：零 JS 开关，浏览器内建 light dismiss 和 Esc。top layer 无视 z-index 与 overflow，专属 <code>::backdrop</code> 做遮罩。三种模式 auto / manual / hint 覆盖不同场景。事件钩子 <code>beforetoggle</code> / <code>toggle</code> 留给动画编排。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：零 JS 菜单（auto）、manual 模态（带 <code>::backdrop</code>）、Toast 队列（manual + JS API）、与锚点定位的黄金搭档（位置 + 层叠）。记住分工：Popover 管层叠与行为，锚点定位管几何位置。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>top layer 无视 z-index 与 overflow，弹出层从此告别 portal 和层叠常量表。</li><li>auto 的链式关闭：非祖先链上的 auto popover 自动互斥，嵌套写内部 DOM。</li><li>Popover 管层叠与行为，锚点定位管几何位置——两者搭档 = 完整原生弹出方案。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>popover=&quot;auto&quot;</code> 和 <code>popover=&quot;manual&quot;</code> 在「关闭行为」上有什么本质区别？Toast 通知该用哪个？</p><p><strong>答</strong>：auto 默认点外部关闭、按 Esc 关闭，并且打开时会关闭其他不在祖先链上的 auto。manual 不自动关闭，必须由显式代码调用 <code>hidePopover()</code>。Toast 通知用 manual：它不需要 light dismiss（通知要持续几秒），也不需要被 Esc 关闭，用 <code>setTimeout</code> 到期后显式关闭并移除 DOM。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>声明式菜单 + manual 模态 + 进出场动画 + 锚点定位搭档 + JS API 与事件：<a href="./../../examples/html/10-popover/index-01-popover.html">examples/html/10-popover/</a></li></ul><h2 id="系列结语" tabindex="-1">系列结语 <a class="header-anchor" href="#系列结语" aria-label="Permalink to &quot;系列结语&quot;">​</a></h2><p>批次 4 完结：锚点定位（EP.31）+ Popover API（EP.32），HTML5 篇扩展至 10 章，全 32 话。CSS 与 HTML 各补一根关键支柱：位置层叠终于告别 JS，前端弹出层体系进入原生时代。</p>',22)])])}const m=e(l,[["render",d]]);export{u as __pageData,m as default};
